import { ActionError } from './types';
import { guardInsert, runSerialized } from './guarded-write';

type ScopeRule = {
  column: string;
  ctxPath: string;
};

const ORG_SCOPE_RULES: ScopeRule[] = [
  {
    "column": "organizationId",
    "ctxPath": "activeOrgId"
  }
];
const OWNER_SCOPE_RULES: ScopeRule[] = [
  {
    "column": "ownerId",
    "ctxPath": "userId"
  }
];
const TEAM_SCOPE_RULES: ScopeRule[] = [
  {
    "column": "teamId",
    "ctxPath": "activeTeamId"
  }
];
const SOFT_DELETE_COLUMNS: string[] = [
  "deletedAt"
];

